// Parse message queuing request
const request = $input.first().json;

// Required fields validation
if (!request.message || !request.queue_operation) {
  return [{
    json: {
      error: 'Missing required fields: message, queue_operation',
      status: 'invalid'
    }
  }];
}

// Create queue request
const queueRequest = {
  ...request,
  queue_id: `queue_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp: new Date().toISOString(),
  processed_by: 'message_queue_system'
};

return [{
  json: queueRequest
}];

// Process message enqueue
const request = $input.first().json;
const message = request.message;

// Calculate priority score
const priorityScore = calculatePriorityScore(message);

// Create queued message
const queuedMessage = {
  queue_id: request.queue_id,
  message_id: message.id || `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  message_data: message,
  priority_score: priorityScore,
  priority_level: getPriorityLevel(priorityScore),
  queue_status: 'queued',
  queue_position: null, // Will be assigned when inserted
  enqueued_at: request.timestamp,
  estimated_delivery: calculateEstimatedDelivery(priorityScore),
  delivery_attempts: 0,
  max_attempts: message.max_delivery_attempts || 3,
  expires_at: calculateExpiryTime(message),
  metadata: {
    queue_type: message.queue_type || 'standard',
    persistent: message.persistent !== false,
    retry_policy: message.retry_policy || 'exponential_backoff',
    depends_on: message.depends_on || [],
    tags: message.tags || []
  }
};

function calculatePriorityScore(msg) {
  let score = 50; // Base score

  // Priority level adjustments
  if (msg.priority === 'critical') score += 40;
  else if (msg.priority === 'high') score += 25;
  else if (msg.priority === 'low') score -= 15;

  // Urgency adjustments
  if (msg.urgency === 'immediate') score += 30;
  else if (msg.urgency === 'urgent') score += 15;

  // Sender importance
  if (msg.from_agent === 'dungeon_master') score += 10;
  if (msg.from_agent === 'conflict_resolution') score += 20;

  // Message type importance
  if (msg.message_type === 'emergency') score += 35;
  if (msg.message_type === 'coordination_request') score += 15;
  if (msg.message_type === 'conflict_report') score += 25;

  // Time sensitivity
  if (msg.time_sensitive) score += 10;

  return Math.min(100, Math.max(0, score));
}

function getPriorityLevel(score) {
  if (score >= 80) return 'critical';
  if (score >= 60) return 'high';
  if (score >= 40) return 'normal';
  if (score >= 20) return 'low';
  return 'background';
}

function calculateEstimatedDelivery(score) {
  const now = new Date();
  let delayMinutes;

  if (score >= 80) delayMinutes = 0;
  else if (score >= 60) delayMinutes = 1;
  else if (score >= 40) delayMinutes = 5;
  else if (score >= 20) delayMinutes = 15;
  else delayMinutes = 30;

  return new Date(now.getTime() + delayMinutes * 60000).toISOString();
}

function calculateExpiryTime(msg) {
  const ttl = msg.ttl_minutes || 60; // Default 1 hour
  return new Date(Date.now() + ttl * 60000).toISOString();
}

return [{
  json: {
    action: 'message_queued',
    queue_request: request,
    queued_message: queuedMessage
  }
}];

// Process dequeue operation
const request = $input.first().json;

const dequeueRequest = {
  queue_id: request.queue_id,
  operation: 'dequeue',
  target_agent: request.target_agent || 'any',
  priority_filter: request.priority_filter || 'all',
  batch_size: request.batch_size || 1,
  ack_timeout: request.ack_timeout || 30,
  timestamp: request.timestamp
};

return [{
  json: {
    action: 'dequeue_requested',
    queue_request: request,
    dequeue_request: dequeueRequest
  }
}];

// Process queue status query
const request = $input.first().json;

const statusQuery = {
  queue_id: request.queue_id,
  query_type: 'queue_status',
  filters: request.filters || {},
  include_metrics: request.include_metrics !== false,
  timestamp: request.timestamp
};

return [{
  json: {
    action: 'status_queried',
    queue_request: request,
    status_query: statusQuery
  }
}];

// Insert message into priority queue and manage queue state
const enqueueResult = $input.first().json;
const queuedMessage = enqueueResult.queued_message;

// Simulate queue management
const queueState = {
  total_messages: 125,
  messages_by_priority: {
    critical: 3,
    high: 12,
    normal: 78,
    low: 25,
    background: 7
  },
  average_wait_time: '2.3 minutes',
  processing_rate: '15.2 messages/minute',
  queue_health: 'healthy'
};

// Insert message based on priority
const insertionResult = {
  message_id: queuedMessage.message_id,
  queue_position: calculateQueuePosition(queuedMessage.priority_score, queueState),
  estimated_wait_time: calculateWaitTime(queuedMessage.priority_score, queueState),
  queue_status: queuedMessage.queue_status,
  enqueued_at: queuedMessage.enqueued_at
};

function calculateQueuePosition(priorityScore, queue) {
  // Estimate position based on priority and current queue state
  let position = 1;

  if (priorityScore >= 80) {
    position = Math.floor(Math.random() * 3) + 1; // Top 3 positions
  } else if (priorityScore >= 60) {
    position = Math.floor(Math.random() * 10) + 4; // Positions 4-13
  } else if (priorityScore >= 40) {
    position = Math.floor(Math.random() * 30) + 14; // Positions 14-43
  } else {
    position = Math.floor(Math.random() * 50) + 44; // Positions 44-93
  }

  return position;
}

function calculateWaitTime(priorityScore, queue) {
  // Estimate wait time based on priority and processing rate
  if (priorityScore >= 80) return '< 1 minute';
  if (priorityScore >= 60) return '1-3 minutes';
  if (priorityScore >= 40) return '3-8 minutes';
  if (priorityScore >= 20) return '8-15 minutes';
  return '15-30 minutes';
}

return [{
  json: {
    action: 'message_inserted',
    insertion_result: insertionResult,
    queue_state: queueState,
    queued_message: queuedMessage
  }
}];

// Check for message dependencies and schedule delivery
const insertResult = $input.first().json;
const queuedMessage = insertResult.queued_message;

// Check if message can be delivered immediately
const canDeliverImmediately = (
  queuedMessage.priority_score >= 80 || // Critical priority
  queuedMessage.metadata.depends_on.length === 0 || // No dependencies
  queuedMessage.message_type === 'emergency' // Emergency messages
);

if (canDeliverImmediately) {
  // Schedule immediate delivery
  return [{
    json: {
      action: 'schedule_immediate_delivery',
      message_id: queuedMessage.message_id,
      delivery_time: 'immediate',
      queue_position: insertResult.insertion_result.queue_position,
      queued_message: queuedMessage
    }
  }];
} else {
  // Schedule for normal queue processing
  return [{
    json: {
      action: 'schedule_queued_delivery',
      message_id: queuedMessage.message_id,
      delivery_time: queuedMessage.estimated_delivery,
      queue_position: insertResult.insertion_result.queue_position,
      estimated_wait: insertResult.insertion_result.estimated_wait_time,
      queued_message: queuedMessage
    }
  }];
}

// Process message delivery confirmation
const deliveryResult = $input.first().json;
const originalMessage = $('Schedule Delivery').first().json;

const deliveryConfirmation = {
  message_id: originalMessage.message_id,
  delivery_status: deliveryResult.status >= 200 && deliveryResult.status < 300 ? 'delivered' : 'failed',
  delivered_at: new Date().toISOString(),
  delivery_response: {
    status_code: deliveryResult.status,
    response_time: deliveryResult.responseTime || 'unknown'
  },
  queue_position: originalMessage.queue_position,
  total_wait_time: calculateTotalWaitTime(originalMessage.queued_message.enqueued_at),
  next_action: determineNextAction(deliveryResult.status)
};

function calculateTotalWaitTime(enqueuedAt) {
  const now = new Date();
  const enqueued = new Date(enqueuedAt);
  const waitMinutes = Math.floor((now - enqueued) / 60000);
  return `${waitMinutes} minutes`;
}

function determineNextAction(statusCode) {
  if (statusCode >= 200 && statusCode < 300) {
    return 'remove_from_queue';
  } else if (statusCode >= 400 && statusCode < 500) {
    return 'retry_or_fail';
  } else {
    return 'retry_with_backoff';
  }
}

return [{
  json: {
    action: 'delivery_confirmed',
    delivery_confirmation: deliveryConfirmation
  }
}];
